from pathlib import Path
import re


def load_sections():
    text = Path('planning.md').read_text()
    markers = list(re.finditer(r'^<!-- prompt: ([a-z-]+) -->$', text, re.M))
    sections = {}
    for index, marker in enumerate(markers):
        name = marker.group(1)
        if name in sections:
            raise ValueError('duplicate section')
        end = markers[index + 1].start() if index + 1 < len(markers) else len(text)
        sections[name] = text[marker.end():end].strip()
    return sections
